"use client";

import { useEffect, useRef, useState } from "react";
import type { ComponentProps } from "react";

import { cn } from "@/lib/utils";
import { usePrefersReducedMotion } from "@/registry/ivan/hooks/use-prefers-reduced-motion";
import { resolveColor } from "@/registry/ivan/lib/dither";
import {
  AMBIENT_FRAME_MS,
  createDitherFieldGrid,
  createLens,
  isLensSettled,
  lensSwell,
  lensTravel,
  packColor,
  paintDitherField,
  rampAt,
  seedOf,
  stepSpring,
} from "@/registry/ivan/lib/dither-field";
import type {
  DitherFieldAnchor,
  DitherFieldGrid,
} from "@/registry/ivan/lib/dither-field";

const maxStepSeconds = 0.05;
const minColumns = 16;
const maxColumns = 256;
const minRows = 8;

const pixelated = { imageRendering: "pixelated" } as const;

interface GridSize {
  columns: number;
  rows: number;
}

const measureGrid = (width: number, height: number, cellSize: number) => {
  const columns = Math.round(
    Math.min(maxColumns, Math.max(minColumns, width / cellSize))
  );
  const cellPixels = width / columns;
  const rows = Math.max(minRows, Math.round(height / Math.max(1, cellPixels)));
  return { columns, rows };
};

interface FieldSurface {
  canvas: HTMLCanvasElement;
  color: number;
  context: CanvasRenderingContext2D;
  grid: DitherFieldGrid;
  host: HTMLElement;
  isAnimated: boolean;
  isInteractive: boolean;
}

const startField = ({
  canvas,
  color,
  context,
  grid,
  host,
  isAnimated,
  isInteractive,
}: FieldSurface) => {
  const image = context.createImageData(grid.columns, grid.rows);
  const pixels = new Uint32Array(image.data.buffer);
  const lens = createLens();
  const pointer = { isInside: false, x: 0, y: 0 };
  let seconds = 0;
  let lastTick: number | null = null;
  let lastPaint = 0;
  let isInView = false;
  let request: number | null = null;

  const paint = () => {
    paintDitherField(
      grid,
      { lens, ramp: isAnimated ? rampAt(seconds) : 0, time: seconds },
      pixels,
      color
    );
    context.putImageData(image, 0, 0);
  };

  canvas.width = grid.columns;
  canvas.height = grid.rows;
  paint();
  canvas.dataset.live = "true";

  if (!isAnimated) {
    return () => {
      canvas.dataset.live = "false";
    };
  }

  const canRun = () => isInView && document.visibilityState === "visible";

  const tick = (now: number) => {
    const step =
      lastTick === null ? 0 : Math.min(maxStepSeconds, (now - lastTick) / 1000);
    lastTick = now;
    seconds += step;
    stepSpring(lens.x, pointer.x, lensTravel, step);
    stepSpring(lens.y, pointer.y, lensTravel, step);
    stepSpring(lens.strength, pointer.isInside ? 1 : 0, lensSwell, step);
    const isLensMoving = pointer.isInside || !isLensSettled(lens);
    if (isLensMoving || now - lastPaint >= AMBIENT_FRAME_MS - 1) {
      paint();
      lastPaint = now;
    }
    request = canRun() ? requestAnimationFrame(tick) : null;
    if (request === null) {
      lastTick = null;
    }
  };

  const schedule = () => {
    if (request !== null) {
      return;
    }
    if (!canRun()) {
      lastTick = null;
      return;
    }
    request = requestAnimationFrame(tick);
  };

  const handleMove = (event: PointerEvent) => {
    if (event.pointerType !== "mouse") {
      return;
    }
    const bounds = canvas.getBoundingClientRect();
    pointer.x = ((event.clientX - bounds.left) / bounds.width) * grid.columns;
    pointer.y = ((event.clientY - bounds.top) / bounds.height) * grid.rows;
    if (isLensSettled(lens)) {
      lens.x.value = pointer.x;
      lens.y.value = pointer.y;
    }
    pointer.isInside = true;
    schedule();
  };

  const handleLeave = () => {
    pointer.isInside = false;
    schedule();
  };

  const observer = new IntersectionObserver(([entry]) => {
    isInView = entry?.isIntersecting ?? false;
    schedule();
  });
  observer.observe(host);
  document.addEventListener("visibilitychange", schedule);
  if (isInteractive) {
    host.addEventListener("pointermove", handleMove);
    host.addEventListener("pointerleave", handleLeave);
  }

  return () => {
    if (request !== null) {
      cancelAnimationFrame(request);
    }
    observer.disconnect();
    document.removeEventListener("visibilitychange", schedule);
    host.removeEventListener("pointermove", handleMove);
    host.removeEventListener("pointerleave", handleLeave);
    canvas.dataset.live = "false";
  };
};

export interface DitherFieldProps extends Omit<
  ComponentProps<"div">,
  "children"
> {
  seed?: string;
  anchor?: DitherFieldAnchor;
  density?: number;
  cellSize?: number;
  interactive?: boolean;
  animated?: boolean;
}

export const DitherField = ({
  seed = "field",
  anchor = "top-right",
  density = 0.62,
  cellSize = 4,
  interactive = true,
  animated = true,
  className,
  ...props
}: DitherFieldProps) => {
  const fieldRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [size, setSize] = useState<GridSize | null>(null);
  const isReduced = usePrefersReducedMotion();
  const cellPixels = Math.min(32, Math.max(2, cellSize));
  const fieldDensity = Math.min(1, Math.max(0, density));

  useEffect(() => {
    const field = fieldRef.current;
    if (!field) {
      return;
    }
    const observer = new ResizeObserver(([entry]) => {
      const box = entry?.contentRect;
      if (!box || box.width === 0 || box.height === 0) {
        return;
      }
      const next = measureGrid(box.width, box.height, cellPixels);
      setSize((current) =>
        current?.columns === next.columns && current.rows === next.rows
          ? current
          : next
      );
    });
    observer.observe(field);
    return () => observer.disconnect();
  }, [cellPixels]);

  useEffect(() => {
    const field = fieldRef.current;
    const host = field?.parentElement;
    const canvas = canvasRef.current;
    const context = canvas?.getContext("2d");
    if (!(size && field && host && canvas && context)) {
      return;
    }
    const grid = createDitherFieldGrid({
      anchor,
      columns: size.columns,
      density: fieldDensity,
      rows: size.rows,
      seed: seedOf(seed),
    });
    const color = packColor(resolveColor(field, getComputedStyle(field).color));
    return startField({
      canvas,
      color,
      context,
      grid,
      host,
      isAnimated: animated && !isReduced,
      isInteractive: interactive,
    });
  }, [size, seed, anchor, fieldDensity, animated, interactive, isReduced]);

  return (
    <div
      aria-hidden
      className={cn(
        "text-foreground pointer-events-none absolute inset-0 -z-10 overflow-hidden opacity-20",
        className
      )}
      ref={fieldRef}
      {...props}
    >
      <canvas
        className="absolute inset-0 block size-full opacity-0 transition-opacity duration-300 ease-out data-[live=true]:opacity-100 motion-reduce:transition-none"
        data-live="false"
        ref={canvasRef}
        style={pixelated}
      />
    </div>
  );
};

import { bayerThreshold } from "./dither";
import type { Rgb } from "./dither";

export type DitherFieldAnchor =
  | "fill"
  | "top"
  | "bottom"
  | "top-right"
  | "center";

export interface DitherFieldGrid {
  bloom: Float32Array;
  columns: number;
  envelope: Float32Array;
  relief: Float32Array;
  rows: number;
  thresholds: Float32Array;
}

export interface Spring {
  value: number;
  velocity: number;
}

export interface SpringConfig {
  damping: number;
  stiffness: number;
}

export interface DitherFieldLens {
  strength: Spring;
  x: Spring;
  y: Spring;
}

export interface DitherFieldFrame {
  lens: DitherFieldLens;
  ramp: number;
  time: number;
}

export const AMBIENT_FRAME_MS = 1000 / 30;
export const RAMP_SECONDS = 2.4;
export const lensTravel: SpringConfig = { damping: 22, stiffness: 170 };
export const lensSwell: SpringConfig = { damping: 14, stiffness: 120 };

const BLOOM_LATTICE = 32;
const BLOOM_FLOOR = 0.4;
const BLOOM_SPAN = 1;
const LENS_RADIUS = 16;
const LENS_REACH = LENS_RADIUS * 2.6;
const LENS_PULL = 0.42;
const LENS_SMEAR = 0.08;
const LENS_SWELL = 0.18;
const LENS_RIPPLE = 0.16;
const RIPPLE_WAVELENGTH = 0.55;
const RIPPLE_SPEED = 3.2;
const SMEAR_LIMIT = 60;
const SETTLED = 0.002;
const GRAIN_SCALE = 14;
const OPAQUE = 0xff_00_00_00;

const bloomLayers = [
  { scale: 1 / 34, weight: 0.6, x: 0.045, y: 0.018 },
  { scale: 1 / 21, weight: 0.4, x: -0.03, y: 0.035 },
] as const;

const smooth = (value: number) => value * value * (3 - 2 * value);

const fade = (edge0: number, edge1: number, value: number) =>
  smooth(Math.min(1, Math.max(0, (value - edge0) / (edge1 - edge0))));

export const seedOf = (text: string) =>
  [...text].reduce(
    (total, character, index) =>
      (total * 31 + (character.codePointAt(0) ?? 0) * (index + 7)) % 9973,
    17
  );

const lattice = (x: number, y: number, seed: number) => {
  const wave = Math.sin(x * 127.1 + y * 311.7 + seed * 74.7) * 43_758.5453;
  return wave - Math.floor(wave);
};

const valueNoise = (x: number, y: number, seed: number) => {
  const baseX = Math.floor(x);
  const baseY = Math.floor(y);
  const blendX = smooth(x - baseX);
  const blendY = smooth(y - baseY);
  const top =
    lattice(baseX, baseY, seed) +
    (lattice(baseX + 1, baseY, seed) - lattice(baseX, baseY, seed)) * blendX;
  const bottom =
    lattice(baseX, baseY + 1, seed) +
    (lattice(baseX + 1, baseY + 1, seed) - lattice(baseX, baseY + 1, seed)) *
      blendX;
  return top + (bottom - top) * blendY;
};

const fbm = (x: number, y: number, seed: number) =>
  0.55 * valueNoise(x, y, seed) +
  0.3 * valueNoise(x * 2.1 + 17, y * 2.1 + 9, seed) +
  0.15 * valueNoise(x * 4.3 + 5, y * 4.3 + 31, seed);

const anchorEnvelopes: Record<
  DitherFieldAnchor,
  (across: number, down: number) => number
> = {
  bottom: (_across, down) => fade(0.2, 0.95, down),
  center: (across, down) =>
    1 - fade(0.2, 0.72, Math.hypot(across - 0.5, (down - 0.5) * 0.8) * 1.4),
  fill: () => 1,
  top: (_across, down) => 1 - fade(0.05, 0.8, down),
  "top-right": (across, down) =>
    fade(0.28, 0.92, across) * (1 - fade(0.05, 0.8, down)),
};

export const createDitherFieldGrid = ({
  anchor,
  columns,
  density,
  rows,
  seed,
}: {
  anchor: DitherFieldAnchor;
  columns: number;
  density: number;
  rows: number;
  seed: number;
}): DitherFieldGrid => {
  const cells = columns * rows;
  const envelope = new Float32Array(cells);
  const relief = new Float32Array(cells);
  const thresholds = new Float32Array(cells);
  const envelopeAt = anchorEnvelopes[anchor];
  for (let row = 0; row < rows; row += 1) {
    for (let column = 0; column < columns; column += 1) {
      const index = row * columns + column;
      const grain = fbm(column / GRAIN_SCALE, row / GRAIN_SCALE, seed);
      envelope[index] =
        envelopeAt(
          column / Math.max(1, columns - 1),
          row / Math.max(1, rows - 1)
        ) * density;
      relief[index] = Math.min(1, Math.max(0, (grain - 0.42) * 2.4 + 0.4));
      thresholds[index] = bayerThreshold(column, row);
    }
  }
  const bloom = new Float32Array(BLOOM_LATTICE * BLOOM_LATTICE);
  for (const index of bloom.keys()) {
    const wave = Math.sin((index + 1) * 12.9898 + seed * 78.233) * 43_758.5453;
    bloom[index] = wave - Math.floor(wave);
  }
  return { bloom, columns, envelope, relief, rows, thresholds };
};

export const createLens = (): DitherFieldLens => ({
  strength: { value: 0, velocity: 0 },
  x: { value: 0, velocity: 0 },
  y: { value: 0, velocity: 0 },
});

export const stepSpring = (
  spring: Spring,
  target: number,
  { damping, stiffness }: SpringConfig,
  seconds: number
) => {
  const acceleration =
    stiffness * (target - spring.value) - damping * spring.velocity;
  spring.velocity += acceleration * seconds;
  spring.value += spring.velocity * seconds;
};

export const isLensSettled = ({ strength }: DitherFieldLens) =>
  Math.abs(strength.value) < SETTLED && Math.abs(strength.velocity) < SETTLED;

export const rampAt = (seconds: number) =>
  smooth(Math.min(1, Math.max(0, seconds / RAMP_SECONDS)));

const wrapLattice = (value: number) =>
  ((value % BLOOM_LATTICE) + BLOOM_LATTICE) % BLOOM_LATTICE;

const latticeAt = (bloom: Float32Array, x: number, y: number) =>
  bloom[wrapLattice(y) * BLOOM_LATTICE + wrapLattice(x)] ?? 0;

const bloomNoise = (bloom: Float32Array, x: number, y: number) => {
  const baseX = Math.floor(x);
  const baseY = Math.floor(y);
  const blendX = smooth(x - baseX);
  const blendY = smooth(y - baseY);
  const top =
    latticeAt(bloom, baseX, baseY) +
    (latticeAt(bloom, baseX + 1, baseY) - latticeAt(bloom, baseX, baseY)) *
      blendX;
  const bottom =
    latticeAt(bloom, baseX, baseY + 1) +
    (latticeAt(bloom, baseX + 1, baseY + 1) -
      latticeAt(bloom, baseX, baseY + 1)) *
      blendX;
  return top + (bottom - top) * blendY;
};

const bloomGain = (
  bloom: Float32Array,
  column: number,
  row: number,
  time: number
) => {
  let total = 0;
  for (const layer of bloomLayers) {
    total +=
      layer.weight *
      bloomNoise(
        bloom,
        column * layer.scale + time * layer.x,
        row * layer.scale + time * layer.y
      );
  }
  const contrast = Math.min(1, Math.max(0, (total - 0.5) * 1.8 + 0.5));
  return BLOOM_FLOOR + BLOOM_SPAN * smooth(contrast);
};

const sampleAt = (
  field: Float32Array,
  columns: number,
  rows: number,
  x: number,
  y: number
) => {
  const column = Math.min(columns - 1, Math.max(0, x));
  const row = Math.min(rows - 1, Math.max(0, y));
  const left = Math.floor(column);
  const top = Math.floor(row);
  const right = Math.min(columns - 1, left + 1);
  const bottom = Math.min(rows - 1, top + 1);
  const blendX = column - left;
  const blendY = row - top;
  const upper =
    (field[top * columns + left] ?? 0) * (1 - blendX) +
    (field[top * columns + right] ?? 0) * blendX;
  const lower =
    (field[bottom * columns + left] ?? 0) * (1 - blendX) +
    (field[bottom * columns + right] ?? 0) * blendX;
  return upper + (lower - upper) * blendY;
};

const clampSmear = (velocity: number) =>
  Math.min(SMEAR_LIMIT, Math.max(-SMEAR_LIMIT, velocity)) * LENS_SMEAR;

export const packColor = ([red, green, blue]: Rgb) =>
  OPAQUE + blue * 0x1_00_00 + green * 0x1_00 + red;

export const paintDitherField = (
  grid: DitherFieldGrid,
  { lens, ramp, time }: DitherFieldFrame,
  pixels: Uint32Array,
  color: number
) => {
  const { bloom, columns, envelope, relief, rows, thresholds } = grid;
  const strength = lens.strength.value;
  const isLensOn = Math.abs(strength) >= SETTLED;
  const lensX = lens.x.value;
  const lensY = lens.y.value;
  const smearX = clampSmear(lens.x.velocity);
  const smearY = clampSmear(lens.y.velocity);
  const ripplePhase = time * RIPPLE_SPEED;
  for (let row = 0; row < rows; row += 1) {
    const offsetY = row - lensY;
    const isRowInLens = isLensOn && Math.abs(offsetY) < LENS_REACH;
    for (let column = 0; column < columns; column += 1) {
      const index = row * columns + column;
      const cellEnvelope = envelope[index] ?? 0;
      if (cellEnvelope === 0) {
        pixels[index] = 0;
        continue;
      }
      const gain =
        ramp === 0 ? 1 : 1 + (bloomGain(bloom, column, row, time) - 1) * ramp;
      let tone = Math.min(1, (relief[index] ?? 0) * gain) * cellEnvelope;
      const offsetX = column - lensX;
      if (isRowInLens && Math.abs(offsetX) < LENS_REACH) {
        const distanceSquared = offsetX * offsetX + offsetY * offsetY;
        const falloff =
          Math.exp(-distanceSquared / (LENS_RADIUS * LENS_RADIUS)) * strength;
        const sampleX =
          column - offsetX * LENS_PULL * falloff - smearX * falloff;
        const sampleY = row - offsetY * LENS_PULL * falloff - smearY * falloff;
        const ripple = Math.sin(
          Math.sqrt(distanceSquared) * RIPPLE_WAVELENGTH - ripplePhase
        );
        const swell = falloff * (LENS_SWELL + LENS_RIPPLE * ripple);
        tone =
          Math.min(
            1,
            sampleAt(relief, columns, rows, sampleX, sampleY) * gain + swell
          ) *
          Math.min(
            cellEnvelope,
            sampleAt(envelope, columns, rows, sampleX, sampleY)
          );
      }
      pixels[index] = tone > (thresholds[index] ?? 1) ? color : 0;
    }
  }
};

export type Rgb = readonly [number, number, number];

export interface DitherFrame {
  data: Uint8ClampedArray;
  height: number;
  width: number;
}

export interface DitherPalette {
  dark: Rgb;
  light: Rgb;
}

export interface DitherOptions {
  contrast: number;
  pixelSize: number;
}

export const BAYER_SIDE = 4;

const TONE_CONTRAST = 18;
const TONE_BRIGHTNESS = 8;

const clampByte = (value: number) => Math.min(255, Math.max(0, value));

const contrastFactor = (contrast: number) => {
  const scaled = contrast * 2.55;
  return (259 * (scaled + 255)) / (255 * (259 - scaled));
};

const buildBayerThresholds = () => {
  let current = [0];
  let side = 1;
  while (side < BAYER_SIDE) {
    const doubled = side * 2;
    const next: number[] = Array.from({ length: doubled * doubled }, () => 0);
    for (let y = 0; y < side; y += 1) {
      for (let x = 0; x < side; x += 1) {
        const value = (current[y * side + x] ?? 0) * 4;
        next[y * doubled + x] = value;
        next[y * doubled + x + side] = value + 2;
        next[(y + side) * doubled + x] = value + 3;
        next[(y + side) * doubled + x + side] = value + 1;
      }
    }
    current = next;
    side = doubled;
  }
  return current.map((value) => (value + 0.5) / current.length);
};

export const bayerThresholds: readonly number[] = buildBayerThresholds();

export const bayerThreshold = (x: number, y: number) =>
  bayerThresholds[(y % BAYER_SIDE) * BAYER_SIDE + (x % BAYER_SIDE)] ?? 0.5;

export const luminance = ([red, green, blue]: Rgb) =>
  0.2126 * red + 0.7152 * green + 0.0722 * blue;

export const orderPalette = (first: Rgb, second: Rgb): DitherPalette =>
  luminance(first) <= luminance(second)
    ? { dark: first, light: second }
    : { dark: second, light: first };

export const resolveColor = (element: Element, color: string): Rgb => {
  const probe = document.createElement("canvas");
  probe.width = 1;
  probe.height = 1;
  const context = probe.getContext("2d", { willReadFrequently: true });
  if (!context) {
    return [0, 0, 0];
  }
  context.fillStyle = color.startsWith("--")
    ? getComputedStyle(element).getPropertyValue(color).trim()
    : color;
  context.fillRect(0, 0, 1, 1);
  const [red = 0, green = 0, blue = 0] = context.getImageData(0, 0, 1, 1).data;
  return [red, green, blue];
};

const pixelLuminance = (data: Uint8ClampedArray, index: number) =>
  luminance([data[index] ?? 0, data[index + 1] ?? 0, data[index + 2] ?? 0]);

const blockTone = (
  frame: DitherFrame,
  blockX: number,
  blockY: number,
  pixelSize: number,
  toneFactor: number,
  ditherFactor: number
) => {
  const x0 = blockX * pixelSize;
  const y0 = blockY * pixelSize;
  const x1 = Math.min(x0 + pixelSize, frame.width);
  const y1 = Math.min(y0 + pixelSize, frame.height);
  let sum = 0;
  for (let y = y0; y < y1; y += 1) {
    for (let x = x0; x < x1; x += 1) {
      const level = pixelLuminance(frame.data, (y * frame.width + x) * 4);
      sum += clampByte(toneFactor * (level - 128) + 128 + TONE_BRIGHTNESS);
    }
  }
  const average = sum / ((x1 - x0) * (y1 - y0));
  return clampByte((average - 128) * ditherFactor + 128);
};

export const ditherFrame = (
  frame: DitherFrame,
  palette: DitherPalette,
  { contrast, pixelSize }: DitherOptions
): DitherFrame => {
  const toneFactor = contrastFactor(TONE_CONTRAST);
  const ditherFactor = contrastFactor(contrast);
  const blocksWide = Math.ceil(frame.width / pixelSize);
  const blocksHigh = Math.ceil(frame.height / pixelSize);
  const lightBlocks = new Uint8Array(blocksWide * blocksHigh);
  for (let blockY = 0; blockY < blocksHigh; blockY += 1) {
    for (let blockX = 0; blockX < blocksWide; blockX += 1) {
      const tone =
        blockTone(frame, blockX, blockY, pixelSize, toneFactor, ditherFactor) /
        255;
      lightBlocks[blockY * blocksWide + blockX] =
        tone > bayerThreshold(blockX, blockY) ? 1 : 0;
    }
  }
  const data = new Uint8ClampedArray(frame.width * frame.height * 4);
  for (let y = 0; y < frame.height; y += 1) {
    const row = Math.floor(y / pixelSize) * blocksWide;
    for (let x = 0; x < frame.width; x += 1) {
      const color = lightBlocks[row + Math.floor(x / pixelSize)]
        ? palette.light
        : palette.dark;
      data.set([...color, 255], (y * frame.width + x) * 4);
    }
  }
  return { data, height: frame.height, width: frame.width };
};

"use client";

import { useSyncExternalStore } from "react";

const reducedMotionQuery = "(prefers-reduced-motion: reduce)";

const subscribe = (onChange: () => void) => {
  const mediaQuery = window.matchMedia(reducedMotionQuery);
  mediaQuery.addEventListener("change", onChange);
  return () => mediaQuery.removeEventListener("change", onChange);
};

const getSnapshot = () => window.matchMedia(reducedMotionQuery).matches;

const getServerSnapshot = () => false;

export const usePrefersReducedMotion = () =>
  useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
